def _interpolate(segments, temperature):
    t = float(temperature)
    for lo, hi, xlo, xhi in segments:
        if lo <= t <= hi:
            return xlo + (t-lo)*(xhi-xlo)/(hi-lo)
    # Rounded coefficients can leave small gaps/shift nominal endpoints <1 C.
    if not segments:
        raise ValueError("empty reference curve")
    lo,hi,xlo,xhi=min(segments,key=lambda v:min(abs(t-v[0]),abs(t-v[1])))
    if min(abs(t-lo),abs(t-hi)) >= 1:
        raise ValueError("temperature outside reference curve")
    return xlo + (t-lo)*(xhi-xlo)/(hi-lo)



def k_emf_uv(temperature):
    t=float(temperature)
    if not -270 <= t <= 1372:
        raise ValueError("K reference range is -270..1372 C")
    if t < 0:
        c=[0.0, .394501280250e-1, .236223735980e-4, -.328589067840e-6,
           -.499048287770e-8, -.675090591730e-10, -.574103274280e-12,
           -.310888728940e-14, -.104516093650e-16, -.198892668780e-19,
           -.163226974860e-22]
        mv=sum(a*t**i for i,a in enumerate(c))
    else:
        c=[-.176004136860e-1,.389212049750e-1,.185587700320e-4,
           -.994575928740e-7,.318409457190e-9,-.560728448890e-12,
           .560750590590e-15,-.320207200030e-18,.971511471520e-22,
           -.121047212750e-25]
        mv=sum(a*t**i for i,a in enumerate(c))
        mv += .1185976*math.exp(-.1183432e-3*(t-126.9686)**2)
    return mv*1000


def tc_emf_uv(name, temperature, cold=False):
    if name == "K":
        return k_emf_uv(temperature)
    curve=CURVES["tc_"+name.lower()]
    return _interpolate(curve["cjc" if cold else "measurement"], temperature)


def rtd_ohms(name, temperature):
    t=float(temperature)
    if name in ("Pt100", "Pt1000"):
        r0=100 if name == "Pt100" else 1000
        return r0*(1+3.9083e-3*t-5.775e-7*t*t+
                   (-4.183e-12*(t-100)*t**3 if t<0 else 0))
    return _interpolate(CURVES["rtd_"+name.lower()]["measurement"],t)/1000


def pv_comparison(sensor, point, pv):
    """Return PV in physical sensor units and expected native engineering PV."""
    p=float(point)
    if sensor.unit == "degC":
        return float(pv), p
    # Analogue Float32 PV uses engineering_value directly: -32000..32000.
    native_expected=-32000+(p-sensor.low)/(sensor.high-sensor.low)*64000
    physical=sensor.low+(float(pv)+32000)/64000*(sensor.high-sensor.low)
    return physical,native_expected


def expected_adc_uv(sensor, point, settings):
    p=float(point)
    if sensor.kind == "TC":
        mode=settings.get("cjc","INT")
        if mode == "DIS":
            cold=0.0
        elif mode == "FIX":
            cold=float(settings.get("fixed_cjc",0))
        else:
            cold=settings.get("calys_cjc_temperature")
            if cold is None:
                return None,"INT: CALYS cold junction temperature unavailable"
            cold=float(cold)
        source="NIST ITS-90" if sensor.name=="K" else "firmware piecewise curve (approximate)"
        # Explicit DIS has zero reference correction, including B type.
        cold_uv=0.0 if cold==0 else tc_emf_uv(sensor.name,cold,cold=True)
        return tc_emf_uv(sensor.name,p)-cold_uv,source+f"; CJC={mode}, {cold:g} C"
    if sensor.kind == "RTD":
        current=250 if sensor.name=="Pt1000" else 500
        source="IEC 60751" if sensor.name in ("Pt100","Pt1000") else "firmware piecewise curve (approximate)"
        return rtd_ohms(sensor.name,p)*current,source+f"; equivalent R*I, I={current} uA"
    if sensor.kind == "VOLT":
        if sensor.unit == "mV":
            return p*1000,"direct mV input"
        return p*1e6*6200/1026200,"voltage divider 6200/1026200"
    if sensor.kind == "CURR":
        return p*1000*49.9*36800/1056800,"49.9 ohm shunt; divider 36800/1056800"
    return None,"no reference model"


def add_comparison(row, sensor, point, settings):
    physical,native_expected=pv_comparison(sensor,point,row["pv"])
    row.update(pv_signal=physical,pv_signal_unit=sensor.unit,
               expected_pv=native_expected,pv_delta=physical-float(point),
               pv_native_delta=float(row["pv"])-native_expected)
    try:
        expected,basis=expected_adc_uv(sensor,point,settings)
    except (ValueError,KeyError) as exc:
        expected,basis=None,"reference unavailable: "+str(exc)
    row.update(expected_adc_uv="" if expected is None else expected,
               adc_delta_uv="" if expected is None else row["microvolts"]-expected,
               adc_reference_basis=basis)


def format_summary(rows, sensor, completed):
    title="溫度差異 (degC)" if sensor.unit=="degC" else "訊號差異 ("+sensor.unit+")"
    lines=["十點測試結果："+("完成" if completed else "中止／失敗，保留已取得結果"),
           f"Sensor={sensor.label}; 差值一律為 實讀 - 預期",title,
           "點 | 設定值 | 實讀值 | 差值 | 原始PV | 預期ADC(uV) | 實讀ADC(uV) | ADC差值(uV) | 狀態"]
    pv_errors=[];adc_errors=[]
    for row in rows:
        if "pv_signal" not in row:
            lines.append(f"{row['point']} | {row['setpoint']} | N/A | N/A | N/A | N/A | N/A | N/A | {row['status']}: {row['error']}")
            continue
        exp=row.get("expected_adc_uv","");delta=row.get("adc_delta_uv","")
        exp_text="N/A" if exp=="" else f"{exp:.3f}"
        delta_text="N/A" if delta=="" else f"{delta:+.3f}"
        lines.append(f"{row['point']} | {row['setpoint']} | {row['pv_signal']:.6f} | {row['pv_delta']:+.6f} | {row['pv']:.6f} | {exp_text} | {row['microvolts']:+d} | {delta_text} | {row['status']} (input_error={row['input_error']})")
        if row['status']=='recorded':
            pv_errors.append(row['pv_delta'])
            if delta!="":adc_errors.append(delta)
    if pv_errors:
        lines.append(f"有效點PV差值：min={min(pv_errors):+.6f}, max={max(pv_errors):+.6f}, 最大絕對差={max(map(abs,pv_errors)):.6f} {sensor.unit}")
    if adc_errors:
        lines.append(f"有效點ADC差值：min={min(adc_errors):+.3f}, max={max(adc_errors):+.3f}, 最大絕對差={max(map(abs,adc_errors)):.3f} uV")
    if sensor.unit!='degC':
        lines.append("實讀值由原始工程PV依韌體比例換回物理單位；原始PV與其預期值另存CSV。")
    if sensor.kind=='TC':
        sources = sorted({r["dut_cjc_source"] for r in rows if "dut_cjc_source" in r})
        lines.append(f"DUT CJC source={sources}；0=關閉，1=內部TMP20，2/3=外部預留。")
        lines.append("ADC uV比較不包含DUT CJC；溫度差的解讀須依DUT來源與接線。")
    if sensor.kind=='RTD':
        lines.append("RTD ADC uV是韌體R*I等效值，不是外部參考電壓實測。")
    lines += ["ADC參考依據："]+list(dict.fromkeys(r.get('adc_reference_basis','') for r in rows if r.get('adc_reference_basis')))
    lines.append("未設定合格公差，不自動判定精度PASS/FAIL；此流程不寫入校正值。")
    return "\n".join(lines)+"\n"

